"use client";

import * as React from "react";

// Base UI has no AspectRatio primitive, so this is a plain box with CSS
// aspect-ratio. It stays relative and full width, so an image placed
// absolutely inside still covers it.

/** Props for the AspectRatio box. `ratio` is width over height. */
export interface AspectRatioProps extends React.ComponentPropsWithoutRef<"div"> {
  ratio?: number;
}

/** Paddock AspectRatio: an unstyled box that keeps its shape as it resizes. */
const AspectRatio = React.forwardRef<HTMLDivElement, AspectRatioProps>(
  ({ ratio = 1, style, ...props }, ref) => (
    <div
      ref={ref}
      data-slot="aspect-ratio"
      style={{ position: "relative", width: "100%", aspectRatio: String(ratio), ...style }}
      {...props}
    />
  ),
);
AspectRatio.displayName = "AspectRatio";

export { AspectRatio };
